parameters.jsonBody:
={{ {
  "model": $env.LLM_MODEL || "gpt-4o-mini",
  "response_format": { "type": "json_object" },
  "temperature": 0.8,
  "messages": [
    {
      "role": "system",
      "content": "Eres un guionista senior especializado en Shorts/TikTok/Reels históricos con obsesión por la retención. Devuelve SOLO JSON válido. Reglas de ritmo: vídeos dinámicos con escenas cortas (2-5 segundos cada una), duración total 40-55 segundos, frases contundentes y directas, sin relleno. Cada escena debe empujar a la siguiente sin pausa. 1) el hook debe abrir con una idea sorprendente, una paradoja, una amenaza, una cifra o una pregunta muy fuerte; 2) la primera escena debe ser la más magnética de todo el vídeo; 3) cada escena debe incluir voiceover, subtitle y visualPrompt coherentes; 4) subtitle debe ser corto, máximo 5 palabras, muy legible en móvil; 5) targetDurationSec por escena debe ser entero entre 2 y 5; 6) usa entre 10 y 12 escenas; 7) suma total entre 40 y 55 segundos; 8) tono divulgativo, dramático y preciso, sin inventar datos; 9) la ÚLTIMA escena debe funcionar como cierre + CTA de seguimiento: el voiceover debe incluir una invitación a seguir la cuenta (ej: 'Síguenos para más historias como esta'), el subtitle debe reflejar el CTA; 10) visualPrompt debe describir una imagen FOTOGRÁFICA REALISTA que podría encontrarse en un banco de imágenes, con detalles visuales concretos (iluminación, encuadre, composición, colores). Evita conceptos abstractos. 11) Cada escena debe incluir imageSearch: 3-5 palabras clave en español separadas por espacios para buscar imágenes reales en bancos de imágenes. imageSearch debe ser diferente de visualPrompt: son keywords cortas de búsqueda, no una descripción. Ejemplo: 'mapa antiguo vela oscuridad'. No uses closingCta separado. Estructura exacta: title, hook, summary, totalTargetDurationSec, scenes. Cada escena: sceneNumber, purpose, narrativeFunction, visualPrompt, imagePrompt, voiceover, subtitle, targetDurationSec. narrativeFunction debe ser una de: hook, setup, escalation, turning_point, consequence, closing."
    },
    {
      "role": "user",
      "content": "Genera un guion histórico muy atractivo para vídeo vertical sobre: " + $json.topic + ". Quiero que el arranque tenga máxima retención y que cada escena se sienta como un avance natural de la anterior."
    }
  ]
} }}

parameters.jsCode:
const content = $input.first().json.choices?.[0]?.message?.content;
if (!content) throw new Error('OpenAI no devolvió contenido');
const raw = JSON.parse(content);
if (!Array.isArray(raw.scenes) || raw.scenes.length < 4) throw new Error('El guion no contiene suficientes escenas');
const scenes = raw.scenes.map((scene, index) => {
  const targetDurationSec = Number(scene.targetDurationSec ?? scene.durationSec ?? 6);
  return {
    sceneNumber: index + 1,
    purpose: scene.purpose || `beat-${index + 1}`,
    narrativeFunction: String(scene.narrativeFunction || '').trim(),
    visualPrompt: String(scene.visualPrompt || scene.imagePrompt || '').trim(),
    imageSearch: String(scene.imageSearch || '').trim(),
    voiceover: String(scene.voiceover || scene.text || '').trim(),
    subtitle: String(scene.subtitle || scene.text || scene.voiceover || '').trim(),
    targetDurationSec: Number.isFinite(targetDurationSec) ? targetDurationSec : 6,
  };
});
const totalTargetDurationSec = scenes.reduce((sum, scene) => sum + scene.targetDurationSec, 0);
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const jobId = `hist-${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
const script = {
  title: String(raw.title || $('Tema').first().json.topic).trim(),
  hook: String(raw.hook || '').trim(),
  summary: String(raw.summary || '').trim(),
  totalTargetDurationSec,
  scenes,
  closingCta: String(raw.closingCta || '').trim()
};
const metadata = {
  jobId,
  status: 'SCRIPT_DRAFT',
  topic: script.title,
  requestedTopic: $('Tema').first().json.topic,
  language: 'es-ES',
  format: 'shorts-9x16',
  targetDurationSeconds: totalTargetDurationSec,
  script,
  createdAt: now.toISOString(),
  updatedAt: now.toISOString()
};
return [{ json: metadata }];
